import{z as n,x as i,o as B,c as l,q as e,j as A,D as a,d as r,s as D,S as s}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"国债期货在组合里","description":"","frontmatter":{"title":"国债期货在组合里","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/bm2-treasury-futures.md","filePath":"quant/bm2-treasury-futures.md","lastUpdated":1791063341000}'),o={name:"quant/bm2-treasury-futures.md"};function d(C,E,p,T,u,_){const t=i("Mermaid");return B(),l("div",null,[E[2]||(E[2]=e('<h1 id="国债期货在组合里" tabindex="-1">国债期货在组合里 <a class="header-anchor" href="#国债期货在组合里" aria-label="Permalink to &quot;国债期货在组合里&quot;">​</a></h1><div class="epigraph"><p>国债期货把久期变成一个每天都能拧的旋钮——只是旋钮的刻度不由名义面额书写，由最便宜可交割券书写。</p><footer>—— 据 Fabozzi 相关章节整理；交割机制细节见 Burghardt 等，The Treasury Bond Basis</footer></div><p><a href="/quant/bm2-bond-indexing">上一课</a>用特征复制逼近指数，误差的另一半根源是现券市场的流动性。本课引入另一种解法：不搬现券，改用一纸合约调久期。国债期货在组合管理里是流动性最好的利率工具之一，但它对冲的从来不是名义标的，而是交割篮里那个随时可能换人的最便宜可交割券（CTD，见 <a href="/quant/ctd-cheapest">CTD 与最便宜可交割</a>）——本课写它的三种用法与一个核心陷阱。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>组合需要在中途移动久期：观点变了、负债变了、或者 <a href="/quant/bm2-ldi">LDI</a> 的对冲比率要调。卖现券再买现券要付两腿价差、冲击成本与结算周期，期限段还未必有货。期货解决的问题正是这个：一张合约、逐日盯市、接近零库存占用地加或减 DV01。但合约的机制立刻带来问题——它的标的不是某一只国债，而是一个转换因子归一后的交割篮；空头拥有交割选择权，期货价格实际追踪 CTD。于是「买多少张」不是面额除以合约面值，而是 DV01 口径的换算：合约对利率的敏感度等于 CTD 的敏感度经转换因子调整后的值。</p><p><span class="marginnote">术语翻译：DV01 读作「一个基点的美元价值」——收益率变动 0.01%（1 个基点）时，头寸盈亏多少美元。比如组合 DV01 为 5000 美元，收益率上行 10 个基点，一阶近似下大约亏 5 万美元。所谓「调久期」，操作上就是在调这个数到目标值。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对冲比率用 DV01 法：\\(N = \\dfrac{DV01_{\\text{目标}} - DV01_{\\text{当前}}}{DV01_{\\text{合约}}}\\)，其中 \\(DV01_{\\text{合约}} \\approx DV01_{\\text{CTD}} / CF\\)。三种典型用法：一是战术调久期，把组合久期快速移到目标再徐徐用现券替换，期货当过桥；二是 LDI 的长效对冲腿，中期负债段用期货覆盖、把长端留给互换；三是基差观点，当期货相对 CTD 偏贵或偏廉时做净基差（这是交易台用法，组合管理只需避开它的反向伤害）。持有期货还必须管展期：临近交割月流动性整体迁往下一合约，展期窗口与成本要进日历，这与指数调仓一样是制度成本而非意外。</p>',8)),(B(),A(s,null,{default:a(()=>[D(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E7%BB%84%E5%90%88%E5%BD%93%E5%89%8D%20DV01%22%5D%20--%3E%20G%5B%22%E7%9B%AE%E6%A0%87%20DV01%20%E7%94%B1%E8%B4%9F%E5%80%BA%E6%88%96%E8%A7%82%E7%82%B9%E7%BB%99%E5%87%BA%22%5D%0A%20%20G%20--%3E%20N%5B%22%E5%90%88%E7%BA%A6%E6%95%B0%E7%AD%89%E4%BA%8E%20DV01%20%E5%B7%AE%E9%99%A4%E4%BB%A5%E5%8D%95%E5%BC%A0%20DV01%22%5D%0A%20%20CTD%5B%22CTD%20%E7%9A%84%20DV01%20%E9%99%A4%E4%BB%A5%E8%BD%AC%E6%8D%A2%E5%9B%A0%E5%AD%90%22%5D%20--%3E%20N%0A%20%20N%20--%3E%20H%5B%22%E5%BB%BA%E4%BB%93%E5%B9%B6%E9%80%90%E6%97%A5%E7%9B%AF%E5%B8%82%22%5D%0A%20%20H%20--%3E%20SW%7B%22CTD%20%E6%98%AF%E5%90%A6%E5%88%87%E6%8D%A2%22%7D%0A%20%20SW%20--%3E%20R%5B%22%E9%87%8D%E7%AE%97%E5%90%88%E7%BA%A6%20DV01%20%E5%B9%B6%E8%B0%83%E4%BB%93%22%5D%0A%20%20SW%20--%3E%20K%5B%22%E7%BB%B4%E6%8C%81%22%5D%0A%20%20R%20--%3E%20H%0A%20%20H%20--%3E%20RO%5B%22%E5%88%B0%E6%9C%9F%E5%89%8D%E6%8C%89%E6%97%A5%E5%8E%86%E5%B1%95%E6%9C%9F%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[r(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么合约 DV01 挂在 CTD 上：转换因子把篮内各券折算成名义券的可交割数量，空头按净基差最小选券交割，套利把期货价格钉在 CTD 的隐含价格上。机制的推论是期货久期不稳定：当收益率跨过切换阈值，CTD 从一只券跳到另一只，合约 DV01 随之跳变——且恰恰在市场大幅移动时发生，此时对冲比率的误差最大。这就是交割期权在组合层面的价格：期货便宜一点点流动性，收走一段久期的确定性。另一条机制是逐日盯市：与现券的应计利息不同，期货的盈亏每天以现金结算，保证金路径在极端日是真实的流动性需求——<a href="/quant/bm2-ldi">LDI 一课</a>的抵押判据在这里同样适用。</p><p><span class="marginnote">一张面值 10 万美元的 10 年期国债期货：若 CTD 久期 6.8、转换因子 0.82，则单张 DV01 约 6.8 × 100000 × 0.0001 ÷ 0.82 ≈ 83 美元；漏掉除以 CF 会把对冲量做错近两成。</span></p><p><span class="marginnote">直觉类比：转换因子像一张「金条折算表」，把成色各异的可交割券折算成标准券的数量——空头交割哪根都行，按表折算即可。折算后按市价买来最便宜的那根就是 CTD；套利把期货价格钉在这根最便宜的券上，于是合约的久期刻度其实由它书写。</span></p>',4)),(B(),A(s,null,{default:a(()=>[D(t,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20Y%5B%22%E6%94%B6%E7%9B%8A%E7%8E%87%E6%B0%B4%E5%B9%B3%E7%A7%BB%E5%8A%A8%22%5D%20--%3E%20L%7B%22CTD%20%E6%98%AF%E5%90%A6%E8%B7%A8%E8%BF%87%E5%88%87%E6%8D%A2%E9%98%88%E5%80%BC%22%7D%0A%20%20L%20--%3E%7C%22%E4%BD%8E%E6%94%B6%E7%9B%8A%E7%8E%87%E7%AB%AF%EF%BC%9A%E9%95%BF%E4%B9%85%E6%9C%9F%E5%88%B8%E6%9C%80%E4%BE%BF%E5%AE%9C%22%7C%20A%5B%22CTD%20%E4%B8%BA%E9%95%BF%E4%B9%85%E6%9C%9F%E5%88%B8%22%5D%0A%20%20L%20--%3E%7C%22%E9%AB%98%E6%94%B6%E7%9B%8A%E7%8E%87%E7%AB%AF%EF%BC%9A%E7%9F%AD%E4%B9%85%E6%9C%9F%E5%88%B8%E6%9C%80%E4%BE%BF%E5%AE%9C%22%7C%20B%5B%22CTD%20%E4%B8%BA%E7%9F%AD%E4%B9%85%E6%9C%9F%E5%88%B8%22%5D%0A%20%20A%20--%3E%20DA%5B%22%E5%90%88%E7%BA%A6%20DV01%20%E5%81%8F%E5%A4%A7%22%5D%0A%20%20B%20--%3E%20DB%5B%22%E5%90%88%E7%BA%A6%20DV01%20%E5%81%8F%E5%B0%8F%22%5D%0A%20%20DA%20--%3E%20J%5B%22%E8%B7%A8%E9%98%88%E5%80%BC%E7%9E%AC%E9%97%B4%EF%BC%9A%E5%90%88%E7%BA%A6%20DV01%20%E8%B7%B3%E5%8F%98%22%5D%0A%20%20DB%20--%3E%20J%0A%20%20J%20--%3E%20H%5B%22%E5%AF%B9%E5%86%B2%E6%AF%94%E7%8E%87%E5%BF%85%E9%A1%BB%E6%8C%89%E9%98%88%E5%80%BC%E9%87%8D%E7%AE%97%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[r(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=e('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>期货只对冲国债成分：拿它对冲信用债组合，利差敞口原封不动，还引入国债—信用基差。对冲比率是时变的，CTD 切换、收益率水平变动都会使它漂移，必须按阈值重算而非按日历偷懒。合约到期档位离散（短、中、长各一档），连续曲线上的久期调整只能插档，插档误差在长端最大。最后，逐日盯市与保证金占用的成本在低波动期不明显，在压力期与折价同时出现——用期货替换现券等于把资金风险从市场换成抵押渠道，这笔交换要在纸上算过再做。</p><p><span class="marginnote">常见误区：拿国债期货对冲信用债组合。期货只跟踪国债利率，信用利差走阔时信用债在跌、期货可能纹丝不动——账面上「对冲比率没错」，损失照常发生。这段没人管的损益叫国债—信用基差，记账时必须单列一栏。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>期货调久期的正确单位是 DV01，合约 DV01 等于 CTD 的 DV01 除以转换因子。</li><li>三种用法：战术过桥、LDI 对冲腿、基差交易；组合管理主要用前两种。</li><li>核心陷阱是 CTD 切换让合约久期在市场大动时跳变，对冲比率须按阈值重算。</li><li>展期与保证金是制度成本，进日历、进抵押预算。</li><li>出处：据 Fabozzi 相关章节与 Burghardt 等 The Treasury Bond Basis 整理；CTD 机制细节见本站 CTD 相关课。</li></ul>',5))])}const F=n(o,[["render",d]]);export{m as __pageData,F as default};
